// ============================================================
// 游戏状态定义
// ============================================================
const { store, commitChange, storeHistory } = createGameStore(
  {
    x: 200,
    y: 150,
    vx: 3,
    vy: 2,
    radius: 20,
    color: '#7c6aef',
  },
  { enableHistory: true }
);

// ============================================================
// 游戏组件
// ============================================================
function Ball() {
  useFrame(() => {
    commitChange('move', (draft) => {
      const nx = draft.x + draft.vx;
      if (nx - draft.radius < 0 || nx + draft.radius > 400) {
        draft.vx = -draft.vx;
      } else {
        draft.x = nx;
      }
      const ny = draft.y + draft.vy;
      if (ny - draft.radius < 0 || ny + draft.radius > 300) {
        draft.vy = -draft.vy;
      } else {
        draft.y = ny;
      }
    });
  });

  return (
    <scene id="main" width={400} height={300} backgroundColor="#1a1a2e">
      <node
        x={store.x - store.radius}
        y={store.y - store.radius}
        width={store.radius * 2}
        height={store.radius * 2}
        shape="circular"
        backgroundColor={store.color}
      />
    </scene>
  );
}

renderGame(() => <Ball />, {
  container: '#game-root',
  autoResize: true,
  bindStore: storeHistory,
});
